css:
.loader { display: grid; grid-template-columns: repeat(3, 1fr); gap: calc(var(--loader-size) * .07); width: var(--loader-size); height: var(--loader-size); }
.loader span { border-radius: calc(var(--loader-size) * .06); background: var(--loader-color); animation: twScaleFade calc(var(--loader-speed) * 1.3) ease-in-out infinite; }
.loader span:nth-child(2), .loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .1); }
.loader span:nth-child(3), .loader span:nth-child(5), .loader span:nth-child(7) { animation-delay: calc(var(--loader-speed) * .2); }
.loader span:nth-child(6), .loader span:nth-child(8) { animation-delay: calc(var(--loader-speed) * .3); }
.loader span:nth-child(9) { animation-delay: calc(var(--loader-speed) * .4); }
@keyframes twScaleFade { 0%, 70%, 100% { transform: scale(.6); opacity: .3; } 35% { transform: scale(1); opacity: 1; } }

